__NUXT_JSONP__("/how-to-apply-for-a-student-visa", {data:[{details:{slug:"en",pageTitle:"How to apply for a student visa | Mentor Language Institute",pageDescription:"There are several steps you must take when applying for a student visa (F1 visa). ",title:"How to apply for a student visa",subtitle:["There are several steps you must take when applying for a student visa (F1 visa). The order of these steps and how you complete them may vary depending on the U.S. Embassy or Consulate in each country. Please consult the instructions on the \u003Ca title=\"Find a U.S. Embassy or Consulate\" href=\"http:\u002F\u002Fwww.usembassy.gov\u002F\" target=\"_blank\"\u003Eembassy or consulate website\u003C\u002Fa\u003E",null,"The student visa instruction video below will give you general instructions on how to apply and obtain a student visa."],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FTvDXtJiPzTM",other_description:["Click on the link below to download the presentation material.","\u003Cstrong\u003EDownload\u003C\u002Fstrong\u003E \u003Ca href=\"\u002Fdocuments\u002FHow_to_Apply_for_a_student_visa-En.pdf\" target=\"_blank\"\u003E\u003Cstrong\u003EHow to apply for a student visa presentation materials\u003C\u002Fstrong\u003E\u003C\u002Fa\u003E"],dir:"\u002Fhow-to-apply-for-a-student-visa",path:"\u002Fhow-to-apply-for-a-student-visa\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:29.664Z",updatedAt:"2025-05-26T12:06:27.787Z"}}],fetch:{},mutations:void 0});